var toString=Object.prototype.toString,hasOwn=Object.prototype.hasOwnProperty;function diff(a,b){var i,j,result=a.slice();for(i=0;i<result.length;i++){for(j=0;j<b.length;j++){if(result[i]===b[j]){result.splice(i,1);i--;break}}}return result}function inArray(elem,array){if(array.indexOf){return array.indexOf(elem)}for(var i=0,length=array.length;i<length;i++){if(array[i]===elem){return i}}return-1}function objectValues(obj){var key,val,vals=QUnit.is("array",obj)?[]:{};for(key in obj){if(hasOwn.call(obj,key)){val=obj[key];vals[key]=val===Object(val)?objectValues(val):val}}return vals}function extend(a,b,undefOnly){for(var prop in b){if(hasOwn.call(b,prop)){if(prop!=="constructor"||a!==global){if(b[prop]===undefined){delete a[prop]}else if(!(undefOnly&&typeof a[prop]!=="undefined")){a[prop]=b[prop]}}}}return a}function objectType(obj){if(typeof obj==="undefined"){return"undefined"}if(obj===null){return"null"}var match=toString.call(obj).match(/^\[object\s(.*)\]$/),type=match&&match[1];switch(type){case"Number":if(isNaN(obj)){return"nan"}return"number";case"String":case"Boolean":case"Array":case"Set":case"Map":case"Date":case"RegExp":case"Function":case"Symbol":return type.toLowerCase()}if(typeof obj==="object"){return"object"}}function is(type,obj){return QUnit.objectType(obj)===type}